  FT["CN-LAW-0001"] = {"id":"CN-LAW-0001","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":26,"structureMode":"article","title":{"zh":"第五届全国人民代表大会常务委员会关于批准《广东省经济特区条例》的决议","en":"Resolution of the Standing Committee of the Fifth National People's Congress on Approving the Regulations on Special Economic Zones in Guangdong Province","orig":"第五届全国人民代表大会常务委员会关于批准《广东省经济特区条例》的决议","vi":"Nghị quyết của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc khóa V về việc phê chuẩn Quy định về đặc khu kinh tế tỉnh Quảng Đông","th":"มติของคณะกรรมาธิการสามัญสภาผู้แทนประชาชนแห่งชาติชุดที่ 5 ว่าด้วยการรับรองข้อบังคับว่าด้วยเขตเศรษฐกิจพิเศษมณฑลกวางตุ้ง","id":"Resolusi Komite Tetap Kongres Rakyat Nasional Ke-5 tentang Pengesahan Peraturan tentang Kawasan Ekonomi Khusus Provinsi Guangdong","ms":"Resolusi Jawatankuasa Tetap Kongres Rakyat Nasional Ke-5 mengenai Pengesahan Peraturan mengenai Zon Ekonomi Khas Wilayah Guangdong"},"level":"law","category":"法律","status":"active","topics":["general"],"issuingBody":"全国人民代表大会常务委员会","promulgatedDate":"1980-08-26","versionDate":"1980-08-26","completenessNote":"全文，第一条至第二十六条，共 26 条；来源为项目数据资源中的官方汇编文件（第五届全国人民代表大会常务委员会关于批准《广东省经济特区条例》的决议_19800826.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\第五届全国人民代表大会常务委员会关于批准《广东省经济特区条例》的决议_19800826.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0001-A1","no":1,"noLabel":{"zh":"第一条"},"chapter":{"zh":"第一章 总 则"},"text":{"zh":"为发展对外经济合作和技术交流，促进社会主义现代化建设，在广东省深圳、珠海、汕头三市分别划出一定区域，设置经济特区（以下简称特区）。特区鼓励外国公民、华侨、港澳同胞及其公司、企业（以下简称客商），投资设厂或者与我方合资设厂，兴办企业和其他事业，并依法保护其资产、应得利润和其他合法权益。"}},{"id":"CN-LAW-0001-A2","no":2,"noLabel":{"zh":"第二条"},"chapter":{"zh":"第一章 总 则"},"text":{"zh":"特区内的企业和个人，必须遵守中华人民共和国的法律、法令和有关规定。本条例有特别规定的，按照本条例的规定执行。"}},{"id":"CN-LAW-0001-A3","no":3,"noLabel":{"zh":"第三条"},"chapter":{"zh":"第一章 总 则"},"text":{"zh":"设立广东省经济特区管理委员会，代表广东省人民政府对各特区实行统一管理。"}},{"id":"CN-LAW-0001-A4","no":4,"noLabel":{"zh":"第四条"},"chapter":{"zh":"第一章 总 则"},"text":{"zh":"特区为客商提供广阔的经营范围，创造良好的经营条件，保证稳定的经营场所。一切在国际经济合作和技术交流中具有积极意义的工业、农业、畜牧业、养殖业、旅游业、住宅和建筑业、高级技术研究制造业，以及客商与我方共同感兴趣的其他行业，都可以投资兴办或者与我方合资兴办。"}},{"id":"CN-LAW-0001-A5","no":5,"noLabel":{"zh":"第五条"},"chapter":{"zh":"第一章 总 则"},"text":{"zh":"特区的土地平整工程和供水、排水、供电、道路、码头、通讯、仓储等各项公共设施，由广东省经济特区管理委员会负责兴建，必要时也可以吸收外资参与兴建。"}},{"id":"CN-LAW-0001-A6","no":6,"noLabel":{"zh":"第六条"},"chapter":{"zh":"第一章 总 则"},"text":{"zh":"各特区分别聘请国内外专家和热心我国现代化建设的有关人士组成顾问委员会，作为该特区的咨询机构。"}},{"id":"CN-LAW-0001-A7","no":7,"noLabel":{"zh":"第七条"},"chapter":{"zh":"第二章 注册和经营"},"text":{"zh":"客商在特区投资设厂，兴办各项经济事业，应向广东省经济特区管理委员会提出申请，经审核、批准后，发给注册证书和土地使用证书。"}},{"id":"CN-LAW-0001-A8","no":8,"noLabel":{"zh":"第八条"},"chapter":{"zh":"第二章 注册和经营"},"text":{"zh":"客商可在特区内设立的中国银行或者其他经我方批准设立的银行开户，并办理有关外汇事宜。\n客商的各项保险，可向特区内设立的中国人民保险公司或者其他经我方批准设立的保险公司投保。"}},{"id":"CN-LAW-0001-A9","no":9,"noLabel":{"zh":"第九条"},"chapter":{"zh":"第二章 注册和经营"},"text":{"zh":"特区企业的产品供国际市场销售；其产品如向我国内地销售，须经广东省经济特区管理委员会核准，并办理海关补税手续。"}},{"id":"CN-LAW-0001-A10","no":10,"noLabel":{"zh":"第十条"},"chapter":{"zh":"第二章 注册和经营"},"text":{"zh":"客商在特区内可以独立经营自己的企业，雇用外籍人员担任技术和管理工作。"}},{"id":"CN-LAW-0001-A11","no":11,"noLabel":{"zh":"第十一条"},"chapter":{"zh":"第二章 注册和经营"},"text":{"zh":"客商在特区所办的企业中途停业，应向广东省经济特区管理委员会申报理由，办理停业手续，清理债权债务；停业后，其资产可转让，资金可汇出。"}},{"id":"CN-LAW-0001-A12","no":12,"noLabel":{"zh":"第十二条"},"chapter":{"zh":"第三章 优惠办法"},"text":{"zh":"特区的土地为中华人民共和国所有。客商用地，按实际需要提供，其使用年限、使用费数额和缴纳办法，根据不同行业和用途，给予优惠，具体办法另行规定。"}},{"id":"CN-LAW-0001-A13","no":13,"noLabel":{"zh":"第十三条"},"chapter":{"zh":"第三章 优惠办法"},"text":{"zh":"特区企业进口生产所必需的机器设备、零配件、原材料、运输工具和其他生产资料，免征进口税；对必需的生活用品、可以根据具体情况、分别征税或者减免进口税。上述物品进口和特区产品出口时，均应向海关办理申报手续。"}},{"id":"CN-LAW-0001-A14","no":14,"noLabel":{"zh":"第十四条"},"chapter":{"zh":"第三章 优惠办法"},"text":{"zh":"特区企业所得税税率为百分之十五。对在本条例公布后两年内投资兴办的企业，或者投资额达五百万美元以上的企业，或者技术性较高、资金周转期较长的企业，给予特别优惠待遇。"}},{"id":"CN-LAW-0001-A15","no":15,"noLabel":{"zh":"第十五条"},"chapter":{"zh":"第三章 优惠办法"},"text":{"zh":"客商在缴纳企业所得税后所得的合法利润，特区企业的外籍职工、华侨职工、港澳职工在缴纳个人所得税后的工资和其他正当收入，可以按照特区外汇管理办法的规定，通过特区内的中国银行或者其他银行汇出。"}},{"id":"CN-LAW-0001-A16","no":16,"noLabel":{"zh":"第十六条"},"chapter":{"zh":"第三章 优惠办法"},"text":{"zh":"客商将所得利润用于在特区内进行再投资为期五年以上者，可申请减免用于再投资部分的所得税。"}},{"id":"CN-LAW-0001-A17","no":17,"noLabel":{"zh":"第十七条"},"chapter":{"zh":"第三章 优惠办法"},"text":{"zh":"鼓励特区企业采用我国生产的机器设备、原材料和其他物资，其价格可按我国当时同类商品的出口价格给予优惠，以外汇结算。这些产品和物资，可凭售货单位的销售凭证直接运往特区。"}},{"id":"CN-LAW-0001-A18","no":18,"noLabel":{"zh":"第十八条"},"chapter":{"zh":"第三章 优惠办法"},"text":{"zh":"凡来往特区的外籍人员、华侨和港澳同胞，出入境均简化手续，给予方便。"}},{"id":"CN-LAW-0001-A19","no":19,"noLabel":{"zh":"第十九条"},"chapter":{"zh":"第四章 劳动管理"},"text":{"zh":"各特区设立劳动服务公司。特区企业雇用中国职员和工人，或者由当地劳动服务公司介绍，或者经广东省经济特区管理委员会同意由客商自行招聘，都由企业考核录用，同职工签订劳动合同。"}},{"id":"CN-LAW-0001-A20","no":20,"noLabel":{"zh":"第二十条"},"chapter":{"zh":"第四章 劳动管理"},"text":{"zh":"特区企业雇用的职工，由该企业按其经营的要求进行管理，必要时可以解雇，其手续按照劳动合同的规定办理。\n特区企业职工可按照劳动合同规定，向企业提请辞职。"}},{"id":"CN-LAW-0001-A21","no":21,"noLabel":{"zh":"第二十一条"},"chapter":{"zh":"第四章 劳动管理"},"text":{"zh":"特区企业中的中国职工工资水平、工资形式、奖励办法，以及劳动保险、国家对职工的各项补贴，按照广东省经济特区管理委员会的规定，由企业同职工签订合同。"}},{"id":"CN-LAW-0001-A22","no":22,"noLabel":{"zh":"第二十二条"},"chapter":{"zh":"第四章 劳动管理"},"text":{"zh":"特区企业应有必要的劳动保护措施，保证职工在安全、卫生的条件下进行工作。"}},{"id":"CN-LAW-0001-A23","no":23,"noLabel":{"zh":"第二十三条"},"chapter":{"zh":"第五章 组织管理"},"text":{"zh":"广东省经济特区管理委员会行使以下职权：\n1.制订特区发展计划并组织实施；\n2.审核、批准客商在特区的投资项目；\n3.办理特区工商登记和土地核配；\n4.协调设在特区内的银行、保险、税务、海关、边检、邮电等机构的工作关系；\n5.为特区企业所需的职工提供来源，并保护职工的正当权益；\n6.举办特区教育、文化、卫生和各项公益事业；\n7.维护特区治安，依法保护特区内人身和财产不受侵犯。"}},{"id":"CN-LAW-0001-A24","no":24,"noLabel":{"zh":"第二十四条"},"chapter":{"zh":"第五章 组织管理"},"text":{"zh":"深圳特区由广东省经济特区管理委员会直接经营管理；珠海、汕头特区设立必要的办事机构。"}},{"id":"CN-LAW-0001-A25","no":25,"noLabel":{"zh":"第二十五条"},"chapter":{"zh":"第五章 组织管理"},"text":{"zh":"为适应特区经济活动的开展，设立广东省经济特区发展公司。公司业务范围：承办资金筹集和信托投资业务；经营或者与客商合资经营特区的有关企业；代理特区客商与内地贸易往来的购销事宜，并提供洽商服务。"}},{"id":"CN-LAW-0001-A26","no":26,"noLabel":{"zh":"第二十六条"},"chapter":{"zh":"第六章 附 则"},"text":{"zh":"本条例由广东省人民代表大会通过，并报中华人民共和国全国人民代表大会常务委员会批准后施行。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"第五届全国人民代表大会常务委员会关于批准《广东省经济特区条例》的决议"},"issuingBody":{"zh":"全国人民代表大会常务委员会"},"promulgatedDate":"1980-08-26","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0002"] = {"id":"CN-LAW-0002","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":1,"structureMode":"WHOLE","title":{"zh":"第五届全国人民代表大会常务委员会关于批准《国务院关于老干部离职休养的暂行规定》的决议","en":"Resolution of the Standing Committee of the Fifth National People's Congress on Approving the Interim Provisions of the State Council on the Retirement and Recuperation of Veteran Cadres","orig":"第五届全国人民代表大会常务委员会关于批准《国务院关于老干部离职休养的暂行规定》的决议","vi":"Nghị quyết của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc khóa năm về việc phê chuẩn Quy định tạm thời của Quốc vụ viện về việc cán bộ lão thành nghỉ việc, nghỉ hưu","th":"มติของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติชุดที่ 5 ว่าด้วยการให้ความเห็นชอบข้อกำหนดชั่วคราวของคณะรัฐมนตรีเกี่ยวกับการลาออกจากตำแหน่งและการเกษียณอายุของเจ้าหน้าที่อาวุโส","id":"Keputusan Komite Tetap Kongres Rakyat Nasional Masa Kelima tentang Persetujuan Ketentuan Sementara Dewan Negara mengenai Pemberhentian dan Pensiun Pegawai Senior","ms":"Keputusan Jawatankuasa Tetap Kongres Rakyat Kebangsaan Penggal Kelima mengenai Kelulusan Peruntukan Sementara Majlis Negara berkenaan Pemberhentian dan Persaraan Pegawai Kanan"},"level":"law","category":"法律","status":"active","topics":["general"],"promulgatedDate":"1980-09-29","completenessNote":"全文，整篇作为一条录入，共 1 条；来源为项目数据资源中的官方汇编文件（第五届全国人民代表大会常务委员会关于批准《国务院关于老干部离职休养的暂行规定》的决议_19800929.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\第五届全国人民代表大会常务委员会关于批准《国务院关于老干部离职休养的暂行规定》的决议_19800929.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0002-A1","no":1,"noLabel":{"zh":"全文"},"text":{"zh":"第五届全国人民代表大会常务委员会关于批准\n《国务院关于老干部离职休养的暂行规定》\n的决议\n（1980年9月29日通过）\n第五届全国人民代表大会常务委员会第十六次会议决定：批准《国务院关于老干部离职休养的暂行规定》，由国务院公布施行。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"第五届全国人民代表大会常务委员会关于批准《国务院关于老干部离职休养的暂行规定》的决议"},"promulgatedDate":"1980-09-29","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0003"] = {"id":"CN-LAW-0003","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":1,"structureMode":"WHOLE","title":{"zh":"第五届全国人民代表大会常务委员会关于批准《国务院关于职工探亲待遇的规定》的决议","en":"Resolution of the Standing Committee of the Fifth National People's Congress on Approving the Provisions of the State Council on the Treatment of Family Visit Leave for Staff and Workers","orig":"第五届全国人民代表大会常务委员会关于批准《国务院关于职工探亲待遇的规定》的决议","vi":"Nghị quyết của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc khóa năm về việc phê chuẩn Quy định của Quốc vụ viện về chế độ đãi ngộ thăm thân của người lao động","th":"มติของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติชุดที่ 5 ว่าด้วยการให้ความเห็นชอบข้อกำหนดของคณะรัฐมนตรีเกี่ยวกับสิทธิประโยชน์การเยี่ยมญาติของลูกจ้าง","id":"Keputusan Komite Tetap Kongres Rakyat Nasional Masa Kelima tentang Persetujuan Ketentuan Dewan Negara mengenai Tunjangan Kunjungan Keluarga bagi Pekerja","ms":"Keputusan Jawatankuasa Tetap Kongres Rakyat Kebangsaan Penggal Kelima mengenai Kelulusan Peruntukan Majlis Negara berkenaan Elaun Melawat Keluarga bagi Pekerja"},"level":"law","category":"法律","status":"active","topics":["general"],"promulgatedDate":"1981-03-06","completenessNote":"全文，整篇作为一条录入，共 1 条；来源为项目数据资源中的官方汇编文件（第五届全国人民代表大会常务委员会关于批准《国务院关于职工探亲待遇的规定》的决议_19810306.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\第五届全国人民代表大会常务委员会关于批准《国务院关于职工探亲待遇的规定》的决议_19810306.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0003-A1","no":1,"noLabel":{"zh":"全文"},"text":{"zh":"第五届全国人民代表大会常务委员会关于批准\n《国务院关于职工探亲待遇的规定》的决议\n（1981年3月6日通过）\n第五届全国人民代表大会常务委员会第十七次会议决定：批准《国务院关于职工探亲待遇的规定》，由国务院公布施行。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"第五届全国人民代表大会常务委员会关于批准《国务院关于职工探亲待遇的规定》的决议"},"promulgatedDate":"1981-03-06","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0004"] = {"id":"CN-LAW-0004","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":10,"structureMode":"article","title":{"zh":"反分裂国家法","en":"Anti-Secession Law","orig":"反分裂国家法","vi":"Luật Chống ly khai nhà nước","th":"พระราชบัญญัติต่อต้านการแบ่งแยกดินแดน","id":"Undang-Undang Anti-Pemisahan Negara","ms":"Akta Anti-Pemisahan Negara"},"level":"law","category":"法律","status":"active","topics":["general"],"issuingBody":"全国人民代表大会","promulgatedDate":"2005-03-14","versionDate":"2005-03-14","completenessNote":"全文，第一条至第十条，共 10 条；来源为项目数据资源中的官方汇编文件（反分裂国家法_20050314.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\反分裂国家法_20050314.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0004-A1","no":1,"noLabel":{"zh":"第一条"},"text":{"zh":"为了反对和遏制“台独”分裂势力分裂国家，促进祖国和平统一，维护台湾海峡地区和平稳定，维护国家主权和领土完整，维护中华民族的根本利益，根据宪法，制定本法。"}},{"id":"CN-LAW-0004-A2","no":2,"noLabel":{"zh":"第二条"},"text":{"zh":"世界上只有一个中国，大陆和台湾同属一个中国，中国的主权和领土完整不容分割。维护国家主权和领土完整是包括台湾同胞在内的全中国人民的共同义务。\n台湾是中国的一部分。国家绝不允许“台独”分裂势力以任何名义、任何方式把台湾从中国分裂出去。"}},{"id":"CN-LAW-0004-A3","no":3,"noLabel":{"zh":"第三条"},"text":{"zh":"台湾问题是中国内战的遗留问题。\n解决台湾问题，实现祖国统一，是中国的内部事务，不受任何外国势力的干涉。"}},{"id":"CN-LAW-0004-A4","no":4,"noLabel":{"zh":"第四条"},"text":{"zh":"完成统一祖国的大业是包括台湾同胞在内的全中国人民的神圣职责。"}},{"id":"CN-LAW-0004-A5","no":5,"noLabel":{"zh":"第五条"},"text":{"zh":"坚持一个中国原则，是实现祖国和平统一的基础。\n以和平方式实现祖国统一，最符合台湾海峡两岸同胞的根本利益。国家以最大的诚意，尽最大的努力，实现和平统一。\n国家和平统一后，台湾可以实行不同于大陆的制度，高度自治。"}},{"id":"CN-LAW-0004-A6","no":6,"noLabel":{"zh":"第六条"},"text":{"zh":"国家采取下列措施，维护台湾海峡地区和平稳定，发展两岸关系：\n（一）鼓励和推动两岸人员往来，增进了解，增强互信；\n（二）鼓励和推动两岸经济交流与合作，直接通邮通航通商，密切两岸经济关系，互利互惠；\n（三）鼓励和推动两岸教育、科技、文化、卫生、体育交流，共同弘扬中华文化的优秀传统；\n（四）鼓励和推动两岸共同打击犯罪；\n（五）鼓励和推动有利于维护台湾海峡地区和平稳定、发展两岸关系的其他活动。\n国家依法保护台湾同胞的权利和利益。"}},{"id":"CN-LAW-0004-A7","no":7,"noLabel":{"zh":"第七条"},"text":{"zh":"国家主张通过台湾海峡两岸平等的协商和谈判，实现和平统一。协商和谈判可以有步骤、分阶段进行，方式可以灵活多样。\n台湾海峡两岸可以就下列事项进行协商和谈判：\n（一）正式结束两岸敌对状态；\n（二）发展两岸关系的规划；\n（三）和平统一的步骤和安排；\n（四）台湾当局的政治地位；\n（五）台湾地区在国际上与其地位相适应的活动空间；\n（六）与实现和平统一有关的其他任何问题。"}},{"id":"CN-LAW-0004-A8","no":8,"noLabel":{"zh":"第八条"},"text":{"zh":"“台独”分裂势力以任何名义、任何方式造成台湾从中国分裂出去的事实，或者发生将会导致台湾从中国分裂出去的重大事变，或者和平统一的可能性完全丧失，国家得采取非和平方式及其他必要措施，捍卫国家主权和领土完整。\n依照前款规定采取非和平方式及其他必要措施，由国务院、中央军事委员会决定和组织实施，并及时向全国人民代表大会常务委员会报告。"}},{"id":"CN-LAW-0004-A9","no":9,"noLabel":{"zh":"第九条"},"text":{"zh":"依照本法规定采取非和平方式及其他必要措施并组织实施时，国家尽最大可能保护台湾平民和在台湾的外国人的生命财产安全和其他正当权益，减少损失；同时，国家依法保护台湾同胞在中国其他地区的权利和利益。"}},{"id":"CN-LAW-0004-A10","no":10,"noLabel":{"zh":"第十条"},"text":{"zh":"本法自公布之日起施行。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"反分裂国家法"},"issuingBody":{"zh":"全国人民代表大会"},"promulgatedDate":"2005-03-14","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0005"] = {"id":"CN-LAW-0005","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":3,"structureMode":"ITEM","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国澳门特别行政区基本法》附件一第七条和附件二第三条的解释","en":"Interpretation of the Standing Committee of the National People's Congress on Article 7 of Annex I and Article 3 of Annex II of the Basic Law of the Macao Special Administrative Region of the People's Republic of China","orig":"全国人民代表大会常务委员会关于《中华人民共和国澳门特别行政区基本法》附件一第七条和附件二第三条的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về Điều 7 Phụ lục một và Điều 3 Phụ lục hai Luật Cơ bản Đặc khu Hành chính Ma Cao nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยข้อ 7 ของภาคผนวกหนึ่งและข้อ 3 ของภาคผนวกสองแห่งกฎหมายพื้นฐานเขตบริหารพิเศษมาเก๊าแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang Butir 7 Lampiran Satu dan Butir 3 Lampiran Dua Undang-Undang Dasar Daerah Administratif Khusus Makau Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Butiran 7 Lampiran Satu dan Butiran 3 Lampiran Dua Undang-Undang Asas Wilayah Pentadbiran Khas Makau Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"issuingBody":"全国人民代表大会常务委员会","promulgatedDate":"2011-12-31","completenessNote":"全文，一、至三、，共 3 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国澳门特别行政区基本法》附件一第七条和附件二第三条的解释_20111231.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国澳门特别行政区基本法》附件一第七条和附件二第三条的解释_20111231.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0005-A1","no":1,"noLabel":{"zh":"一、"},"text":{"zh":"上述两个附件中规定的二〇〇九年及以后行政长官的产生办法、立法会的产生办法“如需修改”，是指可以进行修改，也可以不进行修改。"}},{"id":"CN-LAW-0005-A2","no":2,"noLabel":{"zh":"二、"},"text":{"zh":"上述两个附件中规定的须经立法会全体议员三分之二多数通过，行政长官同意，并报全国人民代表大会常务委员会批准或者备案，是指行政长官的产生办法和立法会的产生办法修改时必经的法律程序。只有经过上述程序，包括最后全国人民代表大会常务委员会依法批准或者备案，该修改方可生效。是否需要进行修改，澳门特别行政区行政长官应向全国人民代表大会常务委员会提出报告，由全国人民代表大会常务委员会依照《中华人民共和国澳门特别行政区基本法》第四十七条和第六十八条规定，根据澳门特别行政区的实际情况确定。修改行政长官产生办法和立法会产生办法的法案，应由澳门特别行政区政府向立法会提出。"}},{"id":"CN-LAW-0005-A3","no":3,"noLabel":{"zh":"三、"},"text":{"zh":"上述两个附件中规定的行政长官的产生办法、立法会的产生办法如果不作修改，行政长官的产生办法仍适用附件一关于行政长官产生办法的规定；立法会的产生办法仍适用附件二关于立法会产生办法的规定。\n现予公告。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国澳门特别行政区基本法》附件一第七条和附件二第三条的解释"},"issuingBody":{"zh":"全国人民代表大会常务委员会"},"promulgatedDate":"2011-12-31","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0006"] = {"id":"CN-LAW-0006","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":5,"structureMode":"ITEM","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国国籍法》在澳门特别行政区实施的几个问题的解释","en":"Interpretation of the Standing Committee of the National People's Congress on Several Issues concerning the Implementation of the Nationality Law of the People's Republic of China in the Macao Special Administrative Region","orig":"全国人民代表大会常务委员会关于《中华人民共和国国籍法》在澳门特别行政区实施的几个问题的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về một số vấn đề khi áp dụng Luật Quốc tịch nước Cộng hòa Nhân dân Trung Hoa tại Đặc khu Hành chính Ma Cao","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยปัญหาหลายประการในการใช้กฎหมายสัญชาติแห่งสาธารณรัฐประชาชนจีนในเขตบริหารพิเศษมาเก๊า","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang Beberapa Masalah dalam Penerapan Undang-Undang Kewarganegaraan Republik Rakyat Tiongkok di Daerah Administratif Khusus Makau","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Beberapa Isu dalam Penggunaan Undang-Undang Kewarganegaraan Republik Rakyat China di Wilayah Pentadbiran Khas Makau"},"level":"law","category":"法律","status":"active","topics":["general"],"issuingBody":"全国人民代表大会常务委员会","promulgatedDate":"1998-12-29","completenessNote":"全文，一、至五、，共 5 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国国籍法》在澳门特别行政区实施的几个问题的解释_19981229.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国国籍法》在澳门特别行政区实施的几个问题的解释_19981229.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0006-A1","no":1,"noLabel":{"zh":"一、"},"text":{"zh":"凡具有中国血统的澳门居民，本人出生在中国领土（含澳门）者，以及其他符合《中华人民共和国国籍法》规定的具有中国国籍的条件者，不论其是否持有葡萄牙旅行证件或身份证件，都是中国公民。\n凡具有中国血统但又具有葡萄牙血统的澳门特别行政区居民，可根据本人意愿，选择中华人民共和国国籍或葡萄牙共和国国籍。确定其中一种国籍，即不具有另一种国籍。上述澳门特别行政区居民，在选择国籍之前，享有澳门特别行政区基本法规定的权利，但受国籍限制的权利除外。"}},{"id":"CN-LAW-0006-A2","no":2,"noLabel":{"zh":"二、"},"text":{"zh":"凡持有葡萄牙旅行证件的澳门中国公民，在澳门特别行政区成立后，可继续使用该证件去其他国家或地区旅行，但在澳门特别行政区和中华人民共和国其他地区不得因持有上述葡萄牙旅行证件而享有葡萄牙的领事保护的权利。"}},{"id":"CN-LAW-0006-A3","no":3,"noLabel":{"zh":"三、"},"text":{"zh":"在外国有居留权的澳门特别行政区的中国公民，可使用外国政府签发的有关证件去其他国家或地区旅行，但在澳门特别行政区和中华人民共和国其他地区不得因持有上述证件而享有外国领事保护的权利。"}},{"id":"CN-LAW-0006-A4","no":4,"noLabel":{"zh":"四、"},"text":{"zh":"在澳门特别行政区成立以前或以后从海外返回澳门的原澳门居民中的中国公民，若变更国籍，可凭有效证件向澳门特别行政区受理国籍申请的机关申报。"}},{"id":"CN-LAW-0006-A5","no":5,"noLabel":{"zh":"五、"},"text":{"zh":"授权澳门特别行政区政府指定其有关机构根据《中华人民共和国国籍法》和以上规定对所有国籍申请事宜作出处理。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国国籍法》在澳门特别行政区实施的几个问题的解释"},"issuingBody":{"zh":"全国人民代表大会常务委员会"},"promulgatedDate":"1998-12-29","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0007"] = {"id":"CN-LAW-0007","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":6,"structureMode":"ITEM","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国国籍法》在香港特别行政区实施的几个问题的解释","en":"Interpretation of the Standing Committee of the National People's Congress on Several Issues concerning the Implementation of the Nationality Law of the People's Republic of China in the Hong Kong Special Administrative Region","orig":"全国人民代表大会常务委员会关于《中华人民共和国国籍法》在香港特别行政区实施的几个问题的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về một số vấn đề khi áp dụng Luật Quốc tịch nước Cộng hòa Nhân dân Trung Hoa tại Đặc khu Hành chính Hồng Kông","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยปัญหาหลายประการในการใช้กฎหมายสัญชาติแห่งสาธารณรัฐประชาชนจีนในเขตบริหารพิเศษฮ่องกง","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang Beberapa Masalah dalam Penerapan Undang-Undang Kewarganegaraan Republik Rakyat Tiongkok di Daerah Administratif Khusus Hong Kong","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Beberapa Isu dalam Penggunaan Undang-Undang Kewarganegaraan Republik Rakyat China di Wilayah Pentadbiran Khas Hong Kong"},"level":"law","category":"法律","status":"active","topics":["general"],"issuingBody":"全国人民代表大会常务委员会","promulgatedDate":"1996-05-15","completenessNote":"全文，一、至六、，共 6 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国国籍法》在香港特别行政区实施的几个问题的解释_19960515.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国国籍法》在香港特别行政区实施的几个问题的解释_19960515.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0007-A1","no":1,"noLabel":{"zh":"一、"},"text":{"zh":"凡具有中国血统的香港居民，本人出生在中国领土（含香港）者，以及其他符合《中华人民共和国国籍法》规定的具有中国国籍的条件者，都是中国公民。"}},{"id":"CN-LAW-0007-A2","no":2,"noLabel":{"zh":"二、"},"text":{"zh":"所有香港中国同胞，不论其是否持有“英国属土公民护照”或者“英国国民（海外）护照”，都是中国公民。自1997年7月1日起，上述中国公民可继续使用英国政府签发的有效旅行证件去其他国家或地区旅行，但在香港特别行政区和中华人民共和国其他地区不得因持有上述英国旅行证件而享有英国的领事保护的权利。"}},{"id":"CN-LAW-0007-A3","no":3,"noLabel":{"zh":"三、"},"text":{"zh":"任何在香港的中国公民，因英国政府的“居英权计划”而获得的英国公民身份，根据《中华人民共和国国籍法》不予承认。这类人仍为中国公民，在香港特别行政区和中华人民共和国其他地区不得享有英国的领事保护的权利。"}},{"id":"CN-LAW-0007-A4","no":4,"noLabel":{"zh":"四、"},"text":{"zh":"在外国有居留权的香港特别行政区的中国公民，可使用外国政府签发的有关证件去其他国家或地区旅行，但在香港特别行政区和中华人民共和国其他地区不得因持有上述证件而享有外国领事保护的权利。"}},{"id":"CN-LAW-0007-A5","no":5,"noLabel":{"zh":"五、"},"text":{"zh":"香港特别行政区的中国公民的国籍发生变更，可凭有效证件向香港特别行政区受理国籍申请的机关申报。"}},{"id":"CN-LAW-0007-A6","no":6,"noLabel":{"zh":"六、"},"text":{"zh":"授权香港特别行政区政府指定其入境事务处为香港特别行政区受理国籍申请的机关，香港特别行政区入境事务处根据《中华人民共和国国籍法》和以上规定对所有国籍申请事宜作出处理。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国国籍法》在香港特别行政区实施的几个问题的解释"},"issuingBody":{"zh":"全国人民代表大会常务委员会"},"promulgatedDate":"1996-05-15","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0008"] = {"id":"CN-LAW-0008","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":1,"structureMode":"ARTICLE","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区基本法》第二十二条第四款和第二十四条第二款第（三）项的解释","en":"Interpretation of the Standing Committee of the National People's Congress on Paragraph 4 of Article 22 and Item (3) of Paragraph 2 of Article 24 of the Basic Law of the Hong Kong Special Administrative Region of the People's Republic of China","orig":"全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区基本法》第二十二条第四款和第二十四条第二款第（三）项的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về khoản 4 Điều 22 và mục (3) khoản 2 Điều 24 Luật Cơ bản Đặc khu Hành chính Hồng Kông nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยวรรคสี่ของมาตรา 22 และข้อ (3) ของวรรคสองมาตรา 24 แห่ง กฎหมายพื้นฐานเขตบริหารพิเศษฮ่องกงแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang Ayat (4) Pasal 22 dan butir (3) Ayat (2) Pasal 24 Undang-Undang Dasar Daerah Administratif Khusus Hong Kong Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Fasal (4) Seksyen 22 dan butiran (3) Fasal (2) Seksyen 24 Undang-Undang Asas Wilayah Pentadbiran Khas Hong Kong Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"issuingBody":"全国人民代表大会常务委员会","promulgatedDate":"1999-06-26","completenessNote":"全文，第二十二条至第二十二条，共 1 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区基本法》第二十二条第四款和第二十四条第二款第（三）项的解释_19990626.doc）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区基本法》第二十二条第四款和第二十四条第二款第（三）项的解释_19990626.doc","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0008-A22","no":22,"noLabel":{"zh":"第二十二条"},"text":{"zh":"第四款和第二十四条第二款\n第（三）项的解释\n（1999年6月26日第九届全国人民代表大会常务委员会第十次会议通过）\n第九届全国人民代表大会常务委员会第十次会议审议了国务院《关于提请解释<中华人民共和国香港特别行政区基本法>第二十二条第四款和第二十四条第二款第（三）项的议案》。国务院的议案是应香港特别行政区行政长官根据《中华人民共和国香港特别行政区基本法》第四十三条和第四十八条第（二）项的有关规定提交的报告提出的。鉴于议案中提出的问题涉及香港特别行政区终审法院1999年1月29日的判决对《中华人民共和国香港特别行政区基本法》有关条款的解释，该有关条款涉及中央管理的事务和中央与香港特别行政区的关系，终审法院在判决前没有依照《中华人民共和国香港特别行政区基本法》第一百五十八条第三款的规定请全国人民代表大会常务委员会作出解释，而终审法院的解释又不符合立法原意，经征询全国人民代表大会常务委员会香港特别行政区基本法委员会的意见，全国人民代表大会常务委员会决定，根据《中华人民共和国宪法》第六十七条第（四）项和《中华人民共和国香港特别行政区基本法》第一百五十八条第一款的规定，对《中华人民共和国香港特别行政区基本法》第二十二条第四款和第二十四条第二款第（三）项的规定，作如下解释：\n一、《中华人民共和国香港特别行政区基本法》第二十二条第四款关于“中国其他地区的人进入香港特别行政区须办理批准手续”的规定，是指各省、自治区、直辖市的人，包括香港永久性居民在内地所生的中国籍子女，不论以何种事由要求进入香港特别行政区，均须依照国家有关法律、行政法规的规定，向其所在地区的有关机关申请办理批准手续，并须持有有关机关制发的有效证件方能进入香港特别行政区。各省、自治区、直辖市的人，包括香港永久性居民在内地所生的中国籍子女，进入香港特别行政区，如未按国家有关法律、行政法规的规定办理相应的批准手续，是不合法的。\n二、《中华人民共和国香港特别行政区基本法》第二十四条第二款前三项规定：“香港特别行政区永久性居民为：（一）在香港特别行政区成立以前或以后在香港出生的中国公民；（二）在香港特别行政区成立以前或以后在香港通常居住连续七年以上的中国公民；（三）第（一）、（二）两项所列居民在香港以外所生的中国籍子女”。其中第（三）项关于“第（一）、（二）两项所列居民在香港以外所生的中国籍子女”的规定，是指无论本人是在香港特别行政区成立以前或以后出生，在其出生时，其父母双方或一方须是符合《中华人民共和国香港特别行政区基本法》第二十四条第二款第（一）项或第（二）项规定条件的人。本解释所阐明的立法原意以及《中华人民共和国香港特别行政区基本法》第二十四条第二款其他各项的立法原意，已体现在1996年8月10日全国人民代表大会香港特别行政区筹备委员会第四次全体会议通过的《关于实施<中华人民共和国香港特别行政区基本法>第二十四条第二款的意见》中。\n本解释公布之后，香港特别行政区法院在引用《中华人民共和国香港特别行政区基本法》有关条款时，应以本解释为准。本解释不影响香港特别行政区终审法院1999年1月29日对有关案件判决的有关诉讼当事人所获得的香港特别行政区居留权。此外，其他任何人是否符合《中华人民共和国香港特别行政区基本法》第二十四条第二款第（三）项规定的条件，均须以本解释为准。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区基本法》第二十二条第四款和第二十四条第二款第（三）项的解释"},"issuingBody":{"zh":"全国人民代表大会常务委员会"},"promulgatedDate":"1999-06-26","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0009"] = {"id":"CN-LAW-0009","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":4,"structureMode":"ITEM","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区基本法》第十三条第一款和第十九条的解释","en":"Interpretation of the Standing Committee of the National People's Congress on Paragraph 1 of Article 13 and Article 19 of the Basic Law of the Hong Kong Special Administrative Region of the People's Republic of China","orig":"全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区基本法》第十三条第一款和第十九条的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về khoản 1 Điều 13 và Điều 19 Luật Cơ bản Đặc khu Hành chính Hồng Kông nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยวรรคหนึ่งของมาตรา 13 และมาตรา 19 แห่งกฎหมายพื้นฐานเขตบริหารพิเศษฮ่องกงแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang Ayat (1) Pasal 13 dan Pasal 19 Undang-Undang Dasar Daerah Administratif Khusus Hong Kong Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Fasal (1) Seksyen 13 dan Seksyen 19 Undang-Undang Asas Wilayah Pentadbiran Khas Hong Kong Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"issuingBody":"全国人民代表大会常务委员会","promulgatedDate":"2011-08-26","completenessNote":"全文，一、至四、，共 4 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区基本法》第十三条第一款和第十九条的解释_20110826.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区基本法》第十三条第一款和第十九条的解释_20110826.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0009-A1","no":1,"noLabel":{"zh":"一、"},"text":{"zh":"关于香港特别行政区终审法院提请解释的第（1）个问题。依照《中华人民共和国宪法》第八十九条第（九）项的规定，国务院即中央人民政府行使管理国家对外事务的职权，国家豁免规则或政策属于国家对外事务中的外交事务范畴，中央人民政府有权决定中华人民共和国的国家豁免规则或政策，在中华人民共和国领域内统一实施。基于上述，根据《中华人民共和国香港特别行政区基本法》第十三条第一款关于“中央人民政府负责管理与香港特别行政区有关的外交事务”的规定，管理与香港特别行政区有关的外交事务属于中央人民政府的权力，中央人民政府有权决定在香港特别行政区适用的国家豁免规则或政策。"}},{"id":"CN-LAW-0009-A2","no":2,"noLabel":{"zh":"二、"},"text":{"zh":"关于香港特别行政区终审法院提请解释的第（2）个问题。依照《中华人民共和国香港特别行政区基本法》第十三条第一款和本解释第一条的规定，中央人民政府有权决定在香港特别行政区适用的国家豁免规则或政策；依照《中华人民共和国香港特别行政区基本法》第十九条和本解释第三条的规定，香港特别行政区法院对中央人民政府决定国家豁免规则或政策的行为无管辖权。因此，香港特别行政区法院在审理案件时遇有外国国家及其财产管辖豁免和执行豁免问题，须适用和实施中央人民政府决定适用于香港特别行政区的国家豁免规则或政策。基于上述，根据《中华人民共和国香港特别行政区基本法》第十三条第一款和第十九条的规定，香港特别行政区，包括香港特别行政区法院，有责任适用或实施中央人民政府决定采取的国家豁免规则或政策，不得偏离上述规则或政策，也不得采取与上述规则或政策不同的规则。"}},{"id":"CN-LAW-0009-A3","no":3,"noLabel":{"zh":"三、"},"text":{"zh":"关于香港特别行政区终审法院提请解释的第（3）个问题。国家豁免涉及一国法院对外国国家及其财产是否拥有管辖权，外国国家及其财产在一国法院是否享有豁免，直接关系到该国的对外关系和国际权利与义务。因此，决定国家豁免规则或政策是一种涉及外交的国家行为。基于上述，《中华人民共和国香港特别行政区基本法》第十九条第三款规定的“国防、外交等国家行为”包括中央人民政府决定国家豁免规则或政策的行为。"}},{"id":"CN-LAW-0009-A4","no":4,"noLabel":{"zh":"四、"},"text":{"zh":"关于香港特别行政区终审法院提请解释的第（4）个问题。依照《中华人民共和国香港特别行政区基本法》第八条和第一百六十条的规定，香港原有法律只有在不抵触《中华人民共和国香港特别行政区基本法》的情况下才予以保留。根据《全国人民代表大会常务委员会关于根据<中华人民共和国香港特别行政区基本法>第一百六十条处理香港原有法律的决定》第四条的规定，采用为香港特别行政区法律的香港原有法律，自1997年7月1日起，在适用时，应作出必要的变更、适应、限制或例外，以符合中华人民共和国对香港恢复行使主权后香港的地位和《基本法》的有关规定。香港特别行政区作为中华人民共和国一个享有高度自治权的地方行政区域，直辖于中央人民政府，必须执行中央人民政府决定的国家豁免规则或政策。香港原有法律中有关国家豁免的规则必须符合上述规定才能在1997年7月1日后继续适用。基于上述，根据《中华人民共和国香港特别行政区基本法》第十三条第一款和第十九条的规定，依照《全国人民代表大会常务委员会关于根据<中华人民共和国香港特别行政区基本法>第一百六十条处理香港原有法律的决定》采用为香港特别行政区法律的香港原有法律中有关国家豁免的规则，从1997年7月1日起，在适用时，须作出必要的变更、适应、限制或例外，以符合中央人民政府决定采取的国家豁免规则或政策。\n现予公告。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区基本法》第十三条第一款和第十九条的解释"},"issuingBody":{"zh":"全国人民代表大会常务委员会"},"promulgatedDate":"2011-08-26","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0010"] = {"id":"CN-LAW-0010","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":1,"structureMode":"ARTICLE","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区基本法》第五十三条第二款的解释","en":"Interpretation of the Standing Committee of the National People's Congress on Paragraph 2 of Article 53 of the Basic Law of the Hong Kong Special Administrative Region of the People's Republic of China","orig":"全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区基本法》第五十三条第二款的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về khoản 2 Điều 53 Luật Cơ bản Đặc khu Hành chính Hồng Kông nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยวรรคสองของมาตรา 53 แห่ง กฎหมายพื้นฐานเขตบริหารพิเศษฮ่องกงแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang Ayat (2) Pasal 53 Undang-Undang Dasar Daerah Administratif Khusus Hong Kong Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Fasal (2) Seksyen 53 Undang-Undang Asas Wilayah Pentadbiran Khas Hong Kong Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"issuingBody":"全国人民代表大会常务委员会","promulgatedDate":"2005-04-27","completenessNote":"全文，第五十三条至第五十三条，共 1 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区基本法》第五十三条第二款的解释_20050427.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区基本法》第五十三条第二款的解释_20050427.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0010-A53","no":53,"noLabel":{"zh":"第五十三条"},"text":{"zh":"第二款的解释\n（2005年4月27日第十届全国人民代表大会常务委员会第十五次会议通过）\n第十届全国人民代表大会常务委员会第十五次会议审议了国务院《关于提请解释<中华人民共和国香港特别行政区基本法>第五十三条第二款的议案》。根据《中华人民共和国宪法》第六十七条第四项和《中华人民共和国香港特别行政区基本法》第一百五十八条第一款的规定，并征询全国人民代表大会常务委员会香港特别行政区基本法委员会的意见，全国人民代表大会常务委员会对《中华人民共和国香港特别行政区基本法》第五十三条第二款的规定，作如下解释：\n《中华人民共和国香港特别行政区基本法》第五十三条第二款中规定：“行政长官缺位时，应在六个月内依本法第四十五条的规定产生新的行政长官。”其中“依本法第四十五条的规定产生新的行政长官”，既包括新的行政长官应依据《中华人民共和国香港特别行政区基本法》第四十五条规定的产生办法产生，也包括新的行政长官的任期应依据《中华人民共和国香港特别行政区基本法》第四十五条规定的产生办法确定。\n《中华人民共和国香港特别行政区基本法》第四十五条第三款规定：“行政长官产生的具体办法由附件一《香港特别行政区行政长官的产生办法》规定。”附件一第一条规定：“行政长官由一个具有广泛代表性的选举委员会根据本法选出，由中央人民政府任命。”第二条规定：“选举委员会每届任期五年。”第七条规定：“二〇〇七年以后各任行政长官的产生办法如需修改，须经立法会全体议员三分之二多数通过，行政长官同意，并报全国人民代表大会常务委员会批准。”上述规定表明，二〇〇七年以前，在行政长官由任期五年的选举委员会选出的制度安排下，如出现行政长官未任满《中华人民共和国香港特别行政区基本法》第四十六条规定的五年任期导致行政长官缺位的情况，新的行政长官的任期应为原行政长官的剩余任期；二〇〇七年以后，如对上述行政长官产生办法作出修改，届时出现行政长官缺位的情况，新的行政长官的任期应根据修改后的行政长官具体产生办法确定。\n现予公告。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区基本法》第五十三条第二款的解释"},"issuingBody":{"zh":"全国人民代表大会常务委员会"},"promulgatedDate":"2005-04-27","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0011"] = {"id":"CN-LAW-0011","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":1,"structureMode":"ARTICLE","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区基本法》第一百零四条的解释","en":"Interpretation of the Standing Committee of the National People's Congress on Article 104 of the Basic Law of the Hong Kong Special Administrative Region of the People's Republic of China","orig":"全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区基本法》第一百零四条的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về Điều 104 Luật Cơ bản Đặc khu Hành chính Hồng Kông nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยมาตรา 104 แห่ง กฎหมายพื้นฐานเขตบริหารพิเศษฮ่องกงแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang Pasal 104 Undang-Undang Dasar Daerah Administratif Khusus Hong Kong Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Seksyen 104 Undang-Undang Asas Wilayah Pentadbiran Khas Hong Kong Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"issuingBody":"全国人民代表大会常务委员会","promulgatedDate":"2016-11-07","completenessNote":"全文，第一百零四条至第一百零四条，共 1 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区基本法》第一百零四条的解释_20161107.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区基本法》第一百零四条的解释_20161107.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0011-A104","no":104,"noLabel":{"zh":"第一百零四条"},"text":{"zh":"的解释\n（2016年11月7日第十二届全国人民代表大会常务委员会第二十四次会议通过）\n第十二届全国人民代表大会常务委员会第二十四次会议审议了委员长会议提请审议《全国人民代表大会常务委员会关于<中华人民共和国香港特别行政区基本法>第一百零四条的解释（草案）》的议案。经征询全国人民代表大会常务委员会香港特别行政区基本法委员会的意见，全国人民代表大会常务委员会决定，根据《中华人民共和国宪法》第六十七条第四项和《中华人民共和国香港特别行政区基本法》第一百五十八条第一款的规定，对《中华人民共和国香港特别行政区基本法》第一百零四条“香港特别行政区行政长官、主要官员、行政会议成员、立法会议员、各级法院法官和其他司法人员在就职时必须依法宣誓拥护中华人民共和国香港特别行政区基本法，效忠中华人民共和国香港特别行政区”的规定，作如下解释：\n一、《中华人民共和国香港特别行政区基本法》第一百零四条规定的“拥护中华人民共和国香港特别行政区基本法，效忠中华人民共和国香港特别行政区”，既是该条规定的宣誓必须包含的法定内容，也是参选或者出任该条所列公职的法定要求和条件。\n二、《中华人民共和国香港特别行政区基本法》第一百零四条规定相关公职人员“就职时必须依法宣誓”，具有以下含义：\n（一）宣誓是该条所列公职人员就职的法定条件和必经程序。未进行合法有效宣誓或者拒绝宣誓，不得就任相应公职，不得行使相应职权和享受相应待遇。\n（二）宣誓必须符合法定的形式和内容要求。宣誓人必须真诚、庄重地进行宣誓，必须准确、完整、庄重地宣读包括“拥护中华人民共和国香港特别行政区基本法，效忠中华人民共和国香港特别行政区”内容的法定誓言。\n（三）宣誓人拒绝宣誓，即丧失就任该条所列相应公职的资格。宣誓人故意宣读与法定誓言不一致的誓言或者以任何不真诚、不庄重的方式宣誓，也属于拒绝宣誓，所作宣誓无效，宣誓人即丧失就任该条所列相应公职的资格。\n（四）宣誓必须在法律规定的监誓人面前进行。监誓人负有确保宣誓合法进行的责任，对符合本解释和香港特别行政区法律规定的宣誓，应确定为有效宣誓；对不符合本解释和香港特别行政区法律规定的宣誓，应确定为无效宣誓，并不得重新安排宣誓。\n三、《中华人民共和国香港特别行政区基本法》第一百零四条所规定的宣誓，是该条所列公职人员对中华人民共和国及其香港特别行政区作出的法律承诺，具有法律约束力。宣誓人必须真诚信奉并严格遵守法定誓言。宣誓人作虚假宣誓或者在宣誓之后从事违反誓言行为的，依法承担法律责任。\n现予公告。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区基本法》第一百零四条的解释"},"issuingBody":{"zh":"全国人民代表大会常务委员会"},"promulgatedDate":"2016-11-07","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0012"] = {"id":"CN-LAW-0012","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":3,"structureMode":"ITEM","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区维护国家安全法》第十四条和第四十七条的解释","en":"Interpretation of the Standing Committee of the National People's Congress on Article 14 and Article 47 of the Law of the People's Republic of China on Safeguarding National Security in the Hong Kong Special Administrative Region","orig":"全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区维护国家安全法》第十四条和第四十七条的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về Điều 14 và Điều 47 Luật Bảo vệ an ninh quốc gia tại Đặc khu Hành chính Hồng Kông nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยมาตรา 14 และมาตรา 47 แห่งกฎหมายว่าด้วยการรักษาความมั่นคงแห่งชาติในเขตบริหารพิเศษฮ่องกงแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang Pasal 14 dan Pasal 47 Undang-Undang Penjagaan Keamanan Nasional di Daerah Administratif Khusus Hong Kong Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Seksyen 14 dan Seksyen 47 Undang-Undang Penjagaan Keselamatan Negara di Wilayah Pentadbiran Khas Hong Kong Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"issuingBody":"全国人民代表大会常务委员会","promulgatedDate":"2022-12-30","completenessNote":"全文，一、至三、，共 3 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区维护国家安全法》第十四条和第四十七条的解释_20221230.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区维护国家安全法》第十四条和第四十七条的解释_20221230.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0012-A1","no":1,"noLabel":{"zh":"一、"},"text":{"zh":"根据《中华人民共和国香港特别行政区维护国家安全法》第十四条的规定，香港特别行政区维护国家安全委员会承担香港特别行政区维护国家安全的法定职责，有权对是否涉及国家安全问题作出判断和决定，工作信息不予公开。香港特别行政区维护国家安全委员会作出的决定不受司法复核，具有可执行的法律效力。香港特别行政区任何行政、立法、司法等机构和任何组织、个人均不得干涉香港特别行政区维护国家安全委员会的工作，均应当尊重并执行香港特别行政区维护国家安全委员会的决定。"}},{"id":"CN-LAW-0012-A2","no":2,"noLabel":{"zh":"二、"},"text":{"zh":"根据《中华人民共和国香港特别行政区维护国家安全法》第四十七条的规定，香港特别行政区法院在审理危害国家安全犯罪案件中遇有涉及有关行为是否涉及国家安全或者有关证据材料是否涉及国家秘密的认定问题，应当向行政长官提出并取得行政长官就该等问题发出的证明书，上述证明书对法院有约束力。"}},{"id":"CN-LAW-0012-A3","no":3,"noLabel":{"zh":"三、"},"text":{"zh":"香港特别行政区行政长官依据《中华人民共和国香港特别行政区维护国家安全法》第十一条的规定于11月28日向中央人民政府提交的有关报告认为，不具有香港特别行政区全面执业资格的海外律师担任危害国家安全犯罪案件的辩护人或者诉讼代理人可能引发国家安全风险。不具有香港特别行政区全面执业资格的海外律师是否可以担任危害国家安全犯罪案件的辩护人或者诉讼代理人的问题，属于《中华人民共和国香港特别行政区维护国家安全法》第四十七条所规定的需要认定的问题，应当取得行政长官发出的证明书。如香港特别行政区法院没有向行政长官提出并取得行政长官就该等问题发出的证明书，香港特别行政区维护国家安全委员会应当根据《中华人民共和国香港特别行政区维护国家安全法》第十四条的规定履行法定职责，对该等情况和问题作出相关判断和决定。\n现予公告。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国香港特别行政区维护国家安全法》第十四条和第四十七条的解释"},"issuingBody":{"zh":"全国人民代表大会常务委员会"},"promulgatedDate":"2022-12-30","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0013"] = {"id":"CN-LAW-0013","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":1,"structureMode":"ARTICLE","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第二百二十八条、第三百四十二条、第四百一十条的解释","en":"Interpretation of the Standing Committee of the National People's Congress on Articles 228, 342 and 410 of the Criminal Law of the People's Republic of China","orig":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第二百二十八条、第三百四十二条、第四百一十条的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về Điều 228, Điều 342 và Điều 410 Bộ luật Hình sự nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยมาตรา 228 มาตรา 342 และมาตรา 410 แห่ง ประมวลกฎหมายอาญาแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang Pasal 228, Pasal 342 dan Pasal 410 Kitab Undang-Undang Hukum Pidana Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Seksyen 228, Seksyen 342 dan Seksyen 410 Kanun Keseksaan Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"issuingBody":"全国人民代表大会常务委员会","promulgatedDate":"2009-08-27","completenessNote":"全文，第三百四十二条至第三百四十二条，共 1 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国刑法》第二百二十八条、第三百四十二条、第四百一十条的解释_20090827.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国刑法》第二百二十八条、第三百四十二条、第四百一十条的解释_20090827.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0013-A342","no":342,"noLabel":{"zh":"第三百四十二条"},"text":{"zh":"、第四百一十条的解释\n（2001年8月31日第九届全国人民代表大会常务委员会第二十三次会议通过 根据2009年8月27日第十一届全国人民代表大会常务委员会第十次会议《关于修改部分法律的决定》修正）\n全国人民代表大会常务委员会讨论了刑法第二百二十八条、第三百四十二条、第四百一十条规定的“违反土地管理法规”和第四百一十条规定的“非法批准征收、征用、占用土地”的含义问题，解释如下：\n刑法第二百二十八条、第三百四十二条、第四百一十条规定的“违反土地管理法规”，是指违反土地管理法、森林法、草原法等法律以及有关行政法规中关于土地管理的规定。\n刑法第四百一十条规定的“非法批准征收、征用、占用土地”，是指非法批准征收、征用、占用耕地、林地等农用地以及其他土地。\n现予公告。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第二百二十八条、第三百四十二条、第四百一十条的解释"},"issuingBody":{"zh":"全国人民代表大会常务委员会"},"promulgatedDate":"2009-08-27","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0014"] = {"id":"CN-LAW-0014","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":1,"structureMode":"ARTICLE","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第二百九十四条第一款的解释","en":"Interpretation of the Standing Committee of the National People's Congress on Paragraph 1 of Article 294 of the Criminal Law of the People's Republic of China","orig":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第二百九十四条第一款的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về khoản 1 Điều 294 Bộ luật Hình sự nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยวรรคหนึ่งของมาตรา 294 แห่ง ประมวลกฎหมายอาญาแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang Ayat (1) Pasal 294 Kitab Undang-Undang Hukum Pidana Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Fasal (1) Seksyen 294 Kanun Keseksaan Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"issuingBody":"全国人民代表大会常务委员会","promulgatedDate":"2002-04-28","completenessNote":"全文，第二百九十四条至第二百九十四条，共 1 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国刑法》第二百九十四条第一款的解释_20020428.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国刑法》第二百九十四条第一款的解释_20020428.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0014-A294","no":294,"noLabel":{"zh":"第二百九十四条"},"text":{"zh":"第一款的解释\n（2002年4月28日第九届全国人民代表大会常务委员会第二十七次会议通过）\n全国人民代表大会常务委员会讨论了刑法第二百九十四条第一款规定的“黑社会性质的组织”的含义问题，解释如下：\n刑法第二百九十四条第一款规定的“黑社会性质的组织”应当同时具备以下特征：\n（一）形成较稳定的犯罪组织，人数较多，有明确的组织者、领导者，骨干成员基本固定；\n（二）有组织地通过违法犯罪活动或者其他手段获取经济利益，具有一定的经济实力，以支持该组织的活动；\n（三）以暴力、威胁或者其他手段，有组织地多次进行违法犯罪活动，为非作恶，欺压、残害群众；\n（四）通过实施违法犯罪活动，或者利用国家工作人员的包庇或者纵容，称霸一方，在一定区域或者行业内，形成非法控制或者重大影响，严重破坏经济、社会生活秩序。\n现予公告。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第二百九十四条第一款的解释"},"issuingBody":{"zh":"全国人民代表大会常务委员会"},"promulgatedDate":"2002-04-28","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0015"] = {"id":"CN-LAW-0015","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":1,"structureMode":"WHOLE","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第二百六十六条的解释","en":"Interpretation of the Standing Committee of the National People's Congress on Article 266 of the Criminal Law of the People's Republic of China","orig":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第二百六十六条的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về Điều 266 Bộ luật Hình sự nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยมาตรา 266 แห่ง ประมวลกฎหมายอาญาแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang Pasal 266 Kitab Undang-Undang Hukum Pidana Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Seksyen 266 Kanun Keseksaan Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"promulgatedDate":"2014-04-24","completenessNote":"全文，整篇作为一条录入，共 1 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国刑法》第二百六十六条的解释_20140424.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国刑法》第二百六十六条的解释_20140424.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0015-A1","no":1,"noLabel":{"zh":"全文"},"text":{"zh":"全国人民代表大会常务委员会关于\n《中华人民共和国刑法》第二百六十六条\n的解释\n（2014年4月24日第十二届全国人民代表大会常务委员会第八次会议通过）\n全国人民代表大会常务委员会根据司法实践中遇到的情况，讨论了刑法第二百六十六条的含义及骗取养老、医疗、工伤、失业、生育等社会保险金或者其他社会保障待遇的行为如何适用刑法有关规定的问题，解释如下：\n以欺诈、伪造证明材料或者其他手段骗取养老、医疗、工伤、失业、生育等社会保险金或者其他社会保障待遇的，属于刑法第二百六十六条规定的诈骗公私财物的行为。\n现予公告。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第二百六十六条的解释"},"promulgatedDate":"2014-04-24","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0016"] = {"id":"CN-LAW-0016","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":7,"structureMode":"ITEM","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第九十三条第二款的解释","en":"Interpretation of the Standing Committee of the National People's Congress on Paragraph 2 of Article 93 of the Criminal Law of the People's Republic of China","orig":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第九十三条第二款的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về khoản 2 Điều 93 Bộ luật Hình sự nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยวรรคสองของมาตรา 93 แห่งประมวลกฎหมายอาญาแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang Ayat (2) Pasal 93 Kitab Undang-Undang Hukum Pidana Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Fasal (2) Seksyen 93 Kanun Keseksaan Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"issuingBody":"全国人民代表大会常务委员会","promulgatedDate":"2000-04-29","completenessNote":"全文，（一）至（七），共 7 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国刑法》第九十三条第二款的解释_20090827.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国刑法》第九十三条第二款的解释_20090827.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0016-A1","no":1,"noLabel":{"zh":"（一）"},"text":{"zh":"救灾、抢险、防汛、优抚、扶贫、移民、救济款物的管理；"}},{"id":"CN-LAW-0016-A2","no":2,"noLabel":{"zh":"（二）"},"text":{"zh":"社会捐助公益事业款物的管理；"}},{"id":"CN-LAW-0016-A3","no":3,"noLabel":{"zh":"（三）"},"text":{"zh":"国有土地的经营和管理；"}},{"id":"CN-LAW-0016-A4","no":4,"noLabel":{"zh":"（四）"},"text":{"zh":"土地征收、征用补偿费用的管理；"}},{"id":"CN-LAW-0016-A5","no":5,"noLabel":{"zh":"（五）"},"text":{"zh":"代征、代缴税款；"}},{"id":"CN-LAW-0016-A6","no":6,"noLabel":{"zh":"（六）"},"text":{"zh":"有关计划生育、户籍、征兵工作；"}},{"id":"CN-LAW-0016-A7","no":7,"noLabel":{"zh":"（七）"},"text":{"zh":"协助人民政府从事的其他行政管理工作。\n村民委员会等村基层组织人员从事前款规定的公务，利用职务上的便利，非法占有公共财物、挪用公款、索取他人财物或者非法收受他人财物，构成犯罪的，适用刑法第三百八十二条和第三百八十三条贪污罪、第三百八十四条挪用公款罪、第三百八十五条和第三百八十六条受贿罪的规定。\n现予公告。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第九十三条第二款的解释"},"issuingBody":{"zh":"全国人民代表大会常务委员会"},"promulgatedDate":"2000-04-29","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0017"] = {"id":"CN-LAW-0017","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":1,"structureMode":"WHOLE","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第九章渎职罪主体适用问题的解释","en":"Interpretation of the Standing Committee of the National People's Congress on the Application of the Subject of the Crime of Dereliction of Duty in Chapter IX of the Criminal Law of the People's Republic of China","orig":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第九章渎职罪主体适用问题的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về vấn đề áp dụng chủ thể của tội phạm về chức vụ tại Chương IX Bộ luật Hình sự nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยปัญหาการใช้บังคับเกี่ยวกับผู้กระทำความผิดฐานความผิดเกี่ยวกับหน้าที่ในภาคที่ 9 แห่ง ประมวลกฎหมายอาญาแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang Masalah Penerapan Subjek Tindak Pidana Jabatan pada Bab IX Kitab Undang-Undang Hukum Pidana Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Isu Penggunaan Subjek Kesalahan Jawatan pada Bab IX Kanun Keseksaan Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"promulgatedDate":"2002-12-28","completenessNote":"全文，整篇作为一条录入，共 1 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国刑法》第九章渎职罪主体适用问题的解释_20021228.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国刑法》第九章渎职罪主体适用问题的解释_20021228.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0017-A1","no":1,"noLabel":{"zh":"全文"},"text":{"zh":"全国人民代表大会常务委员会\n关于《中华人民共和国刑法》第九章渎职罪\n主体适用问题的解释\n（2002年12月28日第九届全国人民代表大会常务委员会第三十一次会议通过）\n全国人大常委会根据司法实践中遇到的情况，讨论了刑法第九章渎职罪主体的适用问题，解释如下：\n在依照法律、法规规定行使国家行政管理职权的组织中从事公务的人员，或者在受国家机关委托代表国家机关行使职权的组织中从事公务的人员，或者虽未列入国家机关人员编制但在国家机关中从事公务的人员，在代表国家机关行使职权时，有渎职行为，构成犯罪的，依照刑法关于渎职罪的规定追究刑事责任。\n现予公告。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第九章渎职罪主体适用问题的解释"},"promulgatedDate":"2002-12-28","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0018"] = {"id":"CN-LAW-0018","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":1,"structureMode":"ARTICLE","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第三百四十一条、第三百一十二条的解释","en":"Interpretation of the Standing Committee of the National People's Congress on Articles 341 and 312 of the Criminal Law of the People's Republic of China","orig":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第三百四十一条、第三百一十二条的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về Điều 341 và Điều 312 Bộ luật Hình sự nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยมาตรา 341 และมาตรา 312 แห่ง ประมวลกฎหมายอาญาแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang Pasal 341 dan Pasal 312 Kitab Undang-Undang Hukum Pidana Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Seksyen 341 dan Seksyen 312 Kanun Keseksaan Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"issuingBody":"全国人民代表大会常务委员会","promulgatedDate":"2014-04-24","completenessNote":"全文，第三百一十二条至第三百一十二条，共 1 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国刑法》第三百四十一条、第三百一十二条的解释_20140424.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国刑法》第三百四十一条、第三百一十二条的解释_20140424.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0018-A312","no":312,"noLabel":{"zh":"第三百一十二条"},"text":{"zh":"的解释\n（2014年4月24日第十二届全国人民代表大会常务委员会第八次会议通过）\n全国人民代表大会常务委员会根据司法实践中遇到的情况，讨论了刑法第三百四十一条第一款规定的非法收购国家重点保护的珍贵、濒危野生动物及其制品的含义和收购刑法第三百四十一条第二款规定的非法狩猎的野生动物如何适用刑法有关规定的问题，解释如下：\n知道或者应当知道是国家重点保护的珍贵、濒危野生动物及其制品，为食用或者其他目的而非法购买的，属于刑法第三百四十一条第一款规定的非法收购国家重点保护的珍贵、濒危野生动物及其制品的行为。\n知道或者应当知道是刑法第三百四十一条第二款规定的非法狩猎的野生动物而购买的，属于刑法第三百一十二条第一款规定的明知是犯罪所得而收购的行为。\n现予公告。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第三百四十一条、第三百一十二条的解释"},"issuingBody":{"zh":"全国人民代表大会常务委员会"},"promulgatedDate":"2014-04-24","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0019"] = {"id":"CN-LAW-0019","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":1,"structureMode":"ARTICLE","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第三百一十三条的解释","en":"Interpretation of the Standing Committee of the National People's Congress on Article 313 of the Criminal Law of the People's Republic of China","orig":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第三百一十三条的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về Điều 313 Bộ luật Hình sự nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยมาตรา 313 แห่ง ประมวลกฎหมายอาญาแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang Pasal 313 Kitab Undang-Undang Hukum Pidana Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Seksyen 313 Kanun Keseksaan Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"issuingBody":"全国人民代表大会常务委员会","promulgatedDate":"2002-08-29","completenessNote":"全文，第三百一十三条至第三百一十三条，共 1 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国刑法》第三百一十三条的解释_20020829.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国刑法》第三百一十三条的解释_20020829.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0019-A313","no":313,"noLabel":{"zh":"第三百一十三条"},"text":{"zh":"的解释\n（2002年8月29日第九届全国人民代表大会常务委员会第二十九次会议通过）\n全国人民代表大会常务委员会讨论了刑法第三百一十三条规定的“对人民法院的判决、裁定有能力执行而拒不执行，情节严重”的含义问题，解释如下：\n刑法第三百一十三条规定的“人民法院的判决、裁定”，是指人民法院依法作出的具有执行内容并已发生法律效力的判决、裁定。人民法院为依法执行支付令、生效的调解书、仲裁裁决、公证债权文书等所作的裁定属于该条规定的裁定。\n下列情形属于刑法第三百一十三条规定的“有能力执行而拒不执行，情节严重”的情形：\n（一）被执行人隐藏、转移、故意毁损财产或者无偿转让财产、以明显不合理的低价转让财产，致使判决、裁定无法执行的；\n（二）担保人或者被执行人隐藏、转移、故意毁损或者转让已向人民法院提供担保的财产，致使判决、裁定无法执行的；\n（三）协助执行义务人接到人民法院协助执行通知书后，拒不协助执行，致使判决、裁定无法执行的；\n（四）被执行人、担保人、协助执行义务人与国家机关工作人员通谋，利用国家机关工作人员的职权妨害执行，致使判决、裁定无法执行的；\n（五）其他有能力执行而拒不执行，情节严重的情形。\n国家机关工作人员有上述第四项行为的，以拒不执行判决、裁定罪的共犯追究刑事责任。国家机关工作人员收受贿赂或者滥用职权，有上述第四项行为的，同时又构成刑法第三百八十五条、第三百九十七条规定之罪的，依照处罚较重的规定定罪处罚。\n现予公告。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第三百一十三条的解释"},"issuingBody":{"zh":"全国人民代表大会常务委员会"},"promulgatedDate":"2002-08-29","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0020"] = {"id":"CN-LAW-0020","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":1,"structureMode":"WHOLE","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第三十条的解释","en":"Interpretation of the Standing Committee of the National People's Congress on Article 30 of the Criminal Law of the People's Republic of China","orig":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第三十条的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về Điều 30 Bộ luật Hình sự nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยมาตรา 30 แห่ง ประมวลกฎหมายอาญาแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang Pasal 30 Kitab Undang-Undang Hukum Pidana Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Seksyen 30 Kanun Keseksaan Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"promulgatedDate":"2014-04-24","completenessNote":"全文，整篇作为一条录入，共 1 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国刑法》第三十条的解释_20140424.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国刑法》第三十条的解释_20140424.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0020-A1","no":1,"noLabel":{"zh":"全文"},"text":{"zh":"全国人民代表大会常务委员会关于\n《中华人民共和国刑法》第三十条的解释\n（2014年4月24日第十二届全国人民代表大会常务委员会第八次会议通过）\n全国人民代表大会常务委员会根据司法实践中遇到的情况，讨论了刑法第三十条的含义及公司、企业、事业单位、机关、团体等单位实施刑法规定的危害社会的行为，法律未规定追究单位的刑事责任的，如何适用刑法有关规定的问题，解释如下：\n公司、企业、事业单位、机关、团体等单位实施刑法规定的危害社会的行为，刑法分则和其他法律未规定追究单位的刑事责任的，对组织、策划、实施该危害社会行为的人依法追究刑事责任。\n现予公告。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第三十条的解释"},"promulgatedDate":"2014-04-24","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0021"] = {"id":"CN-LAW-0021","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":1,"structureMode":"ARTICLE","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第一百五十八条、第一百五十九条的解释","en":"Interpretation of the Standing Committee of the National People's Congress on Articles 158 and 159 of the Criminal Law of the People's Republic of China","orig":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第一百五十八条、第一百五十九条的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về Điều 158 và Điều 159 Bộ luật Hình sự nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยมาตรา 158 และมาตรา 159 แห่ง ประมวลกฎหมายอาญาแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang Pasal 158 dan Pasal 159 Kitab Undang-Undang Hukum Pidana Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Seksyen 158 dan Seksyen 159 Kanun Keseksaan Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"issuingBody":"全国人民代表大会常务委员会","promulgatedDate":"2014-04-24","completenessNote":"全文，第一百五十九条至第一百五十九条，共 1 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国刑法》第一百五十八条、第一百五十九条的解释_20140424.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国刑法》第一百五十八条、第一百五十九条的解释_20140424.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0021-A159","no":159,"noLabel":{"zh":"第一百五十九条"},"text":{"zh":"的解释\n（2014年4月24日第十二届全国人民代表大会常务委员会第八次会议通过）\n全国人民代表大会常务委员会讨论了公司法修改后刑法第一百五十八条、第一百五十九条对实行注册资本实缴登记制、认缴登记制的公司的适用范围问题，解释如下：\n刑法第一百五十八条、第一百五十九条的规定，只适用于依法实行注册资本实缴登记制的公司。\n现予公告。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》第一百五十八条、第一百五十九条的解释"},"issuingBody":{"zh":"全国人民代表大会常务委员会"},"promulgatedDate":"2014-04-24","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0022"] = {"id":"CN-LAW-0022","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":1,"structureMode":"WHOLE","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》有关出口退税、抵扣税款的其他发票规定的解释","en":"Interpretation of the Standing Committee of the National People's Congress on the Provisions of the Criminal Law concerning Other Invoices for Export Tax Refunds and Tax Credits","orig":"全国人民代表大会常务委员会关于《中华人民共和国刑法》有关出口退税、抵扣税款的其他发票规定的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về quy định về các loại hoá đơn khác dùng cho hoàn thuế xuất khẩu và khấu trừ thuế Bộ luật Hình sự nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยบทบัญญัติเกี่ยวกับใบกำกับภาษีประเภทอื่นที่ใช้สำหรับการคืนภาษีส่งออกและการหักภาษี ประมวลกฎหมายอาญาแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang ketentuan tentang Faktur Pajak Jenis Lain untuk Pengembalian Pajak Ekspor dan Pengkreditan Pajak Kitab Undang-Undang Hukum Pidana Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai peruntukan tentang Invois Cukai Jenis Lain bagi Pemulangan Cukai Eksport dan Kredit Cukai Kanun Keseksaan Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"promulgatedDate":"2005-12-29","completenessNote":"全文，整篇作为一条录入，共 1 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国刑法》有关出口退税、抵扣税款的其他发票规定的解释_20051229.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国刑法》有关出口退税、抵扣税款的其他发票规定的解释_20051229.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0022-A1","no":1,"noLabel":{"zh":"全文"},"text":{"zh":"全国人民代表大会常务委员会\n关于《中华人民共和国刑法》有关出口退税、\n抵扣税款的其他发票规定的解释\n（2005年12月29日第十届全国人民代表大会常务委员会第十九次会议通过）\n全国人民代表大会常务委员会根据司法实践中遇到的情况，讨论了刑法规定的“出口退税、抵扣税款的其他发票”的含义问题，解释如下：\n刑法规定的“出口退税、抵扣税款的其他发票”，是指除增值税专用发票以外的，具有出口退税、抵扣税款功能的收付款凭证或者完税凭证。\n现予公告。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》有关出口退税、抵扣税款的其他发票规定的解释"},"promulgatedDate":"2005-12-29","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0023"] = {"id":"CN-LAW-0023","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":1,"structureMode":"WHOLE","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》有关文物的规定适用于具有科学价值的古脊椎动物化石、古人类化石的解释","en":"Interpretation of the Standing Committee of the National People's Congress on the Application of the Provisions of the Criminal Law concerning Cultural Relics to Vertebrate Paleontological Fossils and Paleoanthropological Fossils of Scientific Value","orig":"全国人民代表大会常务委员会关于《中华人民共和国刑法》有关文物的规定适用于具有科学价值的古脊椎动物化石、古人类化石的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về việc áp dụng quy định về cổ vật đối với hoá thạch động vật có xương sống cổ và hoá thạch người cổ có giá trị khoa học Bộ luật Hình sự nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยการใช้บทบัญญัติเกี่ยวกับโบราณวัตถุกับซากดึกดำบรรพ์สัตว์มีกระดูกสันหลังโบราณและซากดึกดำบรรพ์มนุษย์โบราณที่มีคุณค่าทางวิทยาศาสตร์ ประมวลกฎหมายอาญาแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang penerapan ketentuan tentang benda purbakala terhadap fosil vertebrata purba dan fosil manusia purba yang bernilai ilmiah Kitab Undang-Undang Hukum Pidana Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai penggunaan peruntukan tentang artifak purba terhadap fosil vertebrata purba dan fosil manusia purba yang bernilai saintifik Kanun Keseksaan Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"issuingBody":"全国人民代表大会常务委员会","promulgatedDate":"2005-12-29","completenessNote":"全文，整篇作为一条录入，共 1 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国刑法》有关文物的规定适用于具有科学价值的古脊椎动物化石、古人类化石的解释_20051229.doc）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国刑法》有关文物的规定适用于具有科学价值的古脊椎动物化石、古人类化石的解释_20051229.doc","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0023-A1","no":1,"noLabel":{"zh":"全文"},"text":{"zh":"全国人民代表大会常务委员会关于\n《中华人民共和国刑法》有关文物的规定\n适用于具有科学价值的古脊椎动物化石、\n古人类化石的解释\n（2005年12月29日第十届全国人民代表大会常务委员会第十九次会议通过）\n全国人民代表大会常务委员会根据司法实践中遇到的情况，讨论了关于走私、盗窃、损毁、倒卖或者非法转让具有科学价值的古脊椎动物化石、古人类化石的行为适用刑法有关规定的问题，解释如下：\n刑法有关文物的规定，适用于具有科学价值的古脊椎动物化石、古人类化石。\n现予公告。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》有关文物的规定适用于具有科学价值的古脊椎动物化石、古人类化石的解释"},"issuingBody":{"zh":"全国人民代表大会常务委员会"},"promulgatedDate":"2005-12-29","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0024"] = {"id":"CN-LAW-0024","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":1,"structureMode":"WHOLE","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》有关信用卡规定的解释","en":"Interpretation of the Standing Committee of the National People's Congress on the Provisions of the Criminal Law concerning Credit Cards","orig":"全国人民代表大会常务委员会关于《中华人民共和国刑法》有关信用卡规定的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về quy định về thẻ tín dụng Bộ luật Hình sự nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยบทบัญญัติเกี่ยวกับบัตรเครดิต ประมวลกฎหมายอาญาแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang ketentuan tentang Kartu Kredit Kitab Undang-Undang Hukum Pidana Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai peruntukan tentang Kad Kredit Kanun Keseksaan Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"promulgatedDate":"2004-12-29","completenessNote":"全文，整篇作为一条录入，共 1 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国刑法》有关信用卡规定的解释_20041229.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国刑法》有关信用卡规定的解释_20041229.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0024-A1","no":1,"noLabel":{"zh":"全文"},"text":{"zh":"全国人民代表大会常务委员会\n关于《中华人民共和国刑法》有关\n信用卡规定的解释\n（2004年12月29日第十届全国人民代表大会常务委员会第十三次会议通过）\n全国人民代表大会常务委员会根据司法实践中遇到的情况，讨论了刑法规定的“信用卡”的含义问题，解释如下：刑法规定的“信用卡”，是指由商业银行或者其他金融机构发行的具有消费支付、信用贷款、转账结算、存取现金等全部功能或者部分功能的电子支付卡。\n现予公告。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑法》有关信用卡规定的解释"},"promulgatedDate":"2004-12-29","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0025"] = {"id":"CN-LAW-0025","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":1,"structureMode":"WHOLE","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑事诉讼法》第二百九十二条的解释","en":"Interpretation of the Standing Committee of the National People's Congress on Article 292 of the Criminal Procedure Law of the People's Republic of China","orig":"全国人民代表大会常务委员会关于《中华人民共和国刑事诉讼法》第二百九十二条的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về Điều 292 Bộ luật Tố tụng Hình sự nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยมาตรา 292 แห่ง ประมวลกฎหมายวิธีพิจารณาความอาญาแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang Pasal 292 Kitab Undang-Undang Hukum Acara Pidana Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Seksyen 292 Kanun Undang-Undang Prosedur Jenayah Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"promulgatedDate":"2025-12-27","completenessNote":"全文，整篇作为一条录入，共 1 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国刑事诉讼法》第二百九十二条的解释_20251227.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国刑事诉讼法》第二百九十二条的解释_20251227.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0025-A1","no":1,"noLabel":{"zh":"全文"},"text":{"zh":"全国人民代表大会常务委员会关于\n《中华人民共和国刑事诉讼法》\n第二百九十二条的解释\n（2025年12月27日第十四届全国人民代表大会常务委员会第十九次会议通过）\n全国人民代表大会常务委员会根据《中华人民共和国立法法》有关规定和司法实践需要，讨论了《中华人民共和国刑事诉讼法》第二百九十二条关于缺席审判程序中有关法律文书送达方式规定的含义问题，解释如下：\n《中华人民共和国刑事诉讼法》第二百九十二条中规定的“被告人所在地法律允许的其他方式”，是指被告人所在地的法律、判例、惯例、司法实践等所规定、承认、认可、接受的各种送达方式，包括但不限于邮寄、公告、公示、电子等送达方式。\n现予公告。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑事诉讼法》第二百九十二条的解释"},"promulgatedDate":"2025-12-27","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0026"] = {"id":"CN-LAW-0026","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":1,"structureMode":"ARTICLE","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑事诉讼法》第二百七十一条第二款的解释","en":"Interpretation of the Standing Committee of the National People's Congress on Paragraph 2 of Article 271 of the Criminal Procedure Law of the People's Republic of China","orig":"全国人民代表大会常务委员会关于《中华人民共和国刑事诉讼法》第二百七十一条第二款的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về khoản 2 Điều 271 Bộ luật Tố tụng Hình sự nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยวรรคสองของมาตรา 271 แห่ง ประมวลกฎหมายวิธีพิจารณาความอาญาแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang Ayat (2) Pasal 271 Kitab Undang-Undang Hukum Acara Pidana Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Fasal (2) Seksyen 271 Kanun Undang-Undang Prosedur Jenayah Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"issuingBody":"全国人民代表大会常务委员会","promulgatedDate":"2014-04-24","completenessNote":"全文，第二百七十一条至第二百七十一条，共 1 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国刑事诉讼法》第二百七十一条第二款的解释_20140424.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国刑事诉讼法》第二百七十一条第二款的解释_20140424.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0026-A271","no":271,"noLabel":{"zh":"第二百七十一条"},"text":{"zh":"第二款的解释\n（2014年4月24日第十二届全国人民代表大会常务委员会第八次会议通过）\n全国人民代表大会常务委员会根据司法实践中遇到的情况，讨论了刑事诉讼法第二百七十一条第二款的含义及被害人对附条件不起诉的案件能否依照第一百七十六条的规定向人民法院起诉的问题，解释如下：\n人民检察院办理未成年人刑事案件，在作出附条件不起诉的决定以及考验期满作出不起诉的决定以前，应当听取被害人的意见。被害人对人民检察院对未成年犯罪嫌疑人作出的附条件不起诉的决定和不起诉的决定，可以向上一级人民检察院申诉，不适用刑事诉讼法第一百七十六条关于被害人可以向人民法院起诉的规定。\n现予公告。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑事诉讼法》第二百七十一条第二款的解释"},"issuingBody":{"zh":"全国人民代表大会常务委员会"},"promulgatedDate":"2014-04-24","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0027"] = {"id":"CN-LAW-0027","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":1,"structureMode":"WHOLE","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑事诉讼法》第二百五十四条第五款、第二百五十七条第二款的解释","en":"Interpretation of the Standing Committee of the National People's Congress on Paragraph 5 of Article 254 and Paragraph 2 of Article 257 of the Criminal Procedure Law of the People's Republic of China","orig":"全国人民代表大会常务委员会关于《中华人民共和国刑事诉讼法》第二百五十四条第五款、第二百五十七条第二款的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về khoản 5 Điều 254 và khoản 2 Điều 257 Bộ luật Tố tụng Hình sự nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยวรรคห้าของมาตรา 254 และวรรคสองของมาตรา 257 แห่ง ประมวลกฎหมายวิธีพิจารณาความอาญาแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang Ayat (5) Pasal 254 dan Ayat (2) Pasal 257 Kitab Undang-Undang Hukum Acara Pidana Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Fasal (5) Seksyen 254 dan Fasal (2) Seksyen 257 Kanun Undang-Undang Prosedur Jenayah Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"promulgatedDate":"2014-04-24","completenessNote":"全文，整篇作为一条录入，共 1 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国刑事诉讼法》第二百五十四条第五款、第二百五十七条第二款的解释_20140424.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国刑事诉讼法》第二百五十四条第五款、第二百五十七条第二款的解释_20140424.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0027-A1","no":1,"noLabel":{"zh":"全文"},"text":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑事诉讼法》第二百五十四条第五款、第二百五十七条第二款的解释\n（2014年4月24日第十二届全国人民代表大会常务委员会第八次会议通过）\n全国人民代表大会常务委员会根据司法实践中遇到的情况，讨论了刑事诉讼法第二百五十四条第五款、第二百五十七条第二款的含义及人民法院决定暂予监外执行的案件，由哪个机关负责组织病情诊断、妊娠检查和生活不能自理的鉴别和由哪个机关对予以收监执行的罪犯送交执行刑罚的问题，解释如下：\n罪犯在被交付执行前，因有严重疾病、怀孕或者正在哺乳自己婴儿的妇女、生活不能自理的原因，依法提出暂予监外执行的申请的，有关病情诊断、妊娠检查和生活不能自理的鉴别，由人民法院负责组织进行。\n根据刑事诉讼法第二百五十七条第二款的规定，对人民法院决定暂予监外执行的罪犯，有刑事诉讼法第二百五十七条第一款规定的情形，依法应当予以收监的，在人民法院作出决定后，由公安机关依照刑事诉讼法第二百五十三条第二款的规定送交执行刑罚。\n现予公告。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑事诉讼法》第二百五十四条第五款、第二百五十七条第二款的解释"},"promulgatedDate":"2014-04-24","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0028"] = {"id":"CN-LAW-0028","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":1,"structureMode":"ARTICLE","title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑事诉讼法》第七十九条第三款的解释","en":"Interpretation of the Standing Committee of the National People's Congress on Paragraph 3 of Article 79 of the Criminal Procedure Law of the People's Republic of China","orig":"全国人民代表大会常务委员会关于《中华人民共和国刑事诉讼法》第七十九条第三款的解释","vi":"Giải thích của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về khoản 3 Điều 79 Bộ luật Tố tụng Hình sự nước Cộng hòa Nhân dân Trung Hoa","th":"การตีความของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยวรรคสามของมาตรา 79 แห่ง ประมวลกฎหมายวิธีพิจารณาความอาญาแห่งสาธารณรัฐประชาชนจีน","id":"Penafsiran Komite Tetap Kongres Rakyat Nasional tentang Ayat (3) Pasal 79 Kitab Undang-Undang Hukum Acara Pidana Republik Rakyat Tiongkok","ms":"Tafsiran Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Fasal (3) Seksyen 79 Kanun Undang-Undang Prosedur Jenayah Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"issuingBody":"全国人民代表大会常务委员会","promulgatedDate":"2014-04-24","completenessNote":"全文，第七十九条至第七十九条，共 1 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于《中华人民共和国刑事诉讼法》第七十九条第三款的解释_20140424.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于《中华人民共和国刑事诉讼法》第七十九条第三款的解释_20140424.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0028-A79","no":79,"noLabel":{"zh":"第七十九条"},"text":{"zh":"第三款的解释\n（2014年4月24日第十二届全国人民代表大会常务委员会第八次会议通过）\n全国人民代表大会常务委员会根据司法实践中遇到的情况，讨论了刑事诉讼法第七十九条第三款关于违反取保候审、监视居住规定情节严重可以逮捕的规定，是否适用于可能判处徒刑以下刑罚的犯罪嫌疑人、被告人的问题，解释如下：\n根据刑事诉讼法第七十九条第三款的规定，对于被取保候审、监视居住的可能判处徒刑以下刑罚的犯罪嫌疑人、被告人，违反取保候审、监视居住规定，严重影响诉讼活动正常进行的，可以予以逮捕。\n现予公告。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于《中华人民共和国刑事诉讼法》第七十九条第三款的解释"},"issuingBody":{"zh":"全国人民代表大会常务委员会"},"promulgatedDate":"2014-04-24","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0029"] = {"id":"CN-LAW-0029","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":12,"structureMode":"ITEM","title":{"zh":"全国人民代表大会常务委员会关于惩治骗购外汇、逃汇和非法买卖外汇犯罪的决定","en":"Decision of the Standing Committee of the National People's Congress on Punishing Crimes of Fraudulent Purchase of Foreign Exchange, Evasion of Foreign Exchange and Illegal Trading of Foreign Exchange","orig":"全国人民代表大会常务委员会关于惩治骗购外汇、逃汇和非法买卖外汇犯罪的决定","vi":"Quyết định của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về trừng trị tội mua ngoại hối bằng gian dối, tội chuyển ngoại hối ra nước ngoài và tội mua bán ngoại hối trái phép","th":"มติของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยการลงโทษความผิดเกี่ยวกับการซื้อเงินตราต่างประเทศโดยฉ้อฉล การยักย้ายเงินตราต่างประเทศออกนอกประเทศ และการซื้อขายเงินตราต่างประเทศโดยมิชอบ","id":"Keputusan Komite Tetap Kongres Rakyat Nasional tentang Penghukuman Tindak Pidana Pembelian Valuta Asing secara Curang, Pelarian Valuta Asing ke Luar Negeri, dan Jual Beli Valuta Asing secara Tidak Sah","ms":"Keputusan Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Penghukuman Jenayah Pembelian Mata Wang Asing secara Curang, Pelarian Mata Wang Asing ke Luar Negara dan Jual Beli Mata Wang Asing secara Tidak Sah"},"level":"law","category":"法律","status":"active","topics":["general"],"issuingBody":"全国人民代表大会常务委员会","promulgatedDate":"1998-12-29","completenessNote":"全文，一、至九、，共 12 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于惩治骗购外汇、逃汇和非法买卖外汇犯罪的决定_19981229.docx）。　编号说明：来源文件内含多份独立文件（或「决定」与正文并存、分节列举），各部分条号自 1 起独立编号，故条号在文内重复；本库按原文如实保留，未作重排与改号。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于惩治骗购外汇、逃汇和非法买卖外汇犯罪的决定_19981229.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0029-A1","no":1,"noLabel":{"zh":"一、"},"text":{"zh":"有下列情形之一，骗购外汇，数额较大的，处五年以下有期徒刑或者拘役，并处骗购外汇数额百分之五以上百分之三十以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处骗购外汇数额百分之五以上百分之三十以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处骗购外汇数额百分之五以上百分之三十以下罚金或者没收财产："}},{"id":"CN-LAW-0029-A1-d2","no":1,"noLabel":{"zh":"（一）"},"text":{"zh":"使用伪造、变造的海关签发的报关单、进口证明、外汇管理部门核准件等凭证和单据的；"},"dupIndex":2},{"id":"CN-LAW-0029-A2","no":2,"noLabel":{"zh":"（二）"},"text":{"zh":"重复使用海关签发的报关单、进口证明、外汇管理部门核准件等凭证和单据的；"}},{"id":"CN-LAW-0029-A3","no":3,"noLabel":{"zh":"（三）"},"text":{"zh":"以其他方式骗购外汇的。\n伪造、变造海关签发的报关单、进口证明、外汇管理部门核准件等凭证和单据，并用于骗购外汇的，依照前款的规定从重处罚。\n明知用于骗购外汇而提供人民币资金的，以共犯论处。\n单位犯前三款罪的，对单位依照第一款的规定判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑。"}},{"id":"CN-LAW-0029-A2-d2","no":2,"noLabel":{"zh":"二、"},"text":{"zh":"买卖伪造、变造的海关签发的报关单、进口证明、外汇管理部门核准件等凭证和单据或者国家机关的其他公文、证件、印章的，依照刑法第二百八十条的规定定罪处罚。"},"dupIndex":2},{"id":"CN-LAW-0029-A3-d2","no":3,"noLabel":{"zh":"三、"},"text":{"zh":"将刑法第一百九十条修改为：公司、企业或者其他单位，违反国家规定，擅自将外汇存放境外，或者将境内的外汇非法转移到境外，数额较大的，对单位判处逃汇数额百分之五以上百分之三十以下罚金，并对其直接负责的主管人员和其他直接责任人员处五年以下有期徒刑或者拘役；数额巨大或者有其他严重情节的，对单位判处逃汇数额百分之五以上百分之三十以下罚金，并对其直接负责的主管人员和其他直接责任人员处五年以上有期徒刑。"},"dupIndex":2},{"id":"CN-LAW-0029-A4","no":4,"noLabel":{"zh":"四、"},"text":{"zh":"在国家规定的交易场所以外非法买卖外汇，扰乱市场秩序，情节严重的，依照刑法第二百二十五条的规定定罪处罚。\n单位犯前款罪的，依照刑法第二百三十一条的规定处罚。"}},{"id":"CN-LAW-0029-A5","no":5,"noLabel":{"zh":"五、"},"text":{"zh":"海关、外汇管理部门以及金融机构、从事对外贸易经营活动的公司、企业或者其他单位的工作人员与骗购外汇或者逃汇的行为人通谋，为其提供购买外汇的有关凭证或者其他便利的，或者明知是伪造、变造的凭证和单据而售汇、付汇的，以共犯论，依照本决定从重处罚。"}},{"id":"CN-LAW-0029-A6","no":6,"noLabel":{"zh":"六、"},"text":{"zh":"海关、外汇管理部门的工作人员严重不负责任，造成大量外汇被骗购或者逃汇，致使国家利益遭受重大损失的，依照刑法第三百九十七条的规定定罪处罚。"}},{"id":"CN-LAW-0029-A7","no":7,"noLabel":{"zh":"七、"},"text":{"zh":"金融机构、从事对外贸易经营活动的公司、企业的工作人员严重不负责任，造成大量外汇被骗购或者逃汇，致使国家利益遭受重大损失的，依照刑法第一百六十七条的规定定罪处罚。"}},{"id":"CN-LAW-0029-A8","no":8,"noLabel":{"zh":"八、"},"text":{"zh":"犯本决定规定之罪，依法被追缴、没收的财物和罚金，一律上缴国库。"}},{"id":"CN-LAW-0029-A9","no":9,"noLabel":{"zh":"九、"},"text":{"zh":"本决定自公布之日起施行。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于惩治骗购外汇、逃汇和非法买卖外汇犯罪的决定"},"issuingBody":{"zh":"全国人民代表大会常务委员会"},"promulgatedDate":"1998-12-29","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
  FT["CN-LAW-0030"] = {"id":"CN-LAW-0030","coverage":"full","language":"zh","sourceName":"中国法律法规汇编（项目数据资源·官方汇编文件）","sourceUrl":"","fetchedAt":"2026-10-02","articleCount":1,"structureMode":"WHOLE","title":{"zh":"全国人民代表大会常务委员会关于对中华人民共和国缔结或者参加的国际条约所规定的罪行行使刑事管辖权的决定","en":"Decision of the Standing Committee of the National People's Congress on Exercising Criminal Jurisdiction over Crimes Prescribed by International Treaties Concluded or Acceded to by the People's Republic of China","orig":"全国人民代表大会常务委员会关于对中华人民共和国缔结或者参加的国际条约所规定的罪行行使刑事管辖权的决定","vi":"Quyết định của Ủy ban Thường vụ Đại hội Đại biểu Nhân dân Toàn quốc về việc thực hiện quyền tài phán hình sự đối với các tội phạm quy định trong điều ước quốc tế mà nước Cộng hòa Nhân dân Trung Hoa ký kết hoặc tham gia","th":"มติของคณะกรรมาธิการสามัญประจำสภาผู้แทนประชาชนแห่งชาติว่าด้วยการใช้เขตอำนาจทางอาญาต่อความผิดที่กำหนดในสนธิสัญญาระหว่างประเทศซึ่งสาธารณรัฐประชาชนจีนได้ลงนามหรือเข้าร่วม","id":"Keputusan Komite Tetap Kongres Rakyat Nasional tentang Pelaksanaan Yurisdiksi Pidana atas Tindak Pidana yang Diatur dalam Perjanjian Internasional yang Ditandatangani atau Diikuti Republik Rakyat Tiongkok","ms":"Keputusan Jawatankuasa Tetap Kongres Rakyat Kebangsaan mengenai Pelaksanaan Bidang Kuasa Jenayah atas Kesalahan yang Diperuntukkan dalam Perjanjian Antarabangsa yang Ditandatangani atau Disertai Republik Rakyat China"},"level":"law","category":"法律","status":"active","topics":["general"],"promulgatedDate":"1987-06-23","completenessNote":"全文，整篇作为一条录入，共 1 条；来源为项目数据资源中的官方汇编文件（全国人民代表大会常务委员会关于对中华人民共和国缔结或者参加的国际条约所规定的罪行行使刑事管辖权的决定_19870623.docx）。","sourceFile":"数据资源\\法律法规（持续更新中）\\法律\\全国人民代表大会常务委员会关于对中华人民共和国缔结或者参加的国际条约所规定的罪行行使刑事管辖权的决定_19870623.docx","country":"CN","countryName":"中国","layer":"cn","articles":[{"id":"CN-LAW-0030-A1","no":1,"noLabel":{"zh":"全文"},"text":{"zh":"全国人民代表大会常务委员会关于对中华人民\n共和国缔结或者参加的国际条约所规定的罪行\n行使刑事管辖权的决定\n（1987年6月23日通过）\n第六届全国人民代表大会常务委员会第二十一次会议决定：对于中华人民共和国缔结或者参加的国际条约所规定的罪行，中华人民共和国在所承担条约义务的范围内，行使刑事管辖权。"}}],"pack":"cn-p01","fulltextMeta":{"country":"CN","level":"law","status":"active","topics":["general"],"title":{"zh":"全国人民代表大会常务委员会关于对中华人民共和国缔结或者参加的国际条约所规定的罪行行使刑事管辖权的决定"},"promulgatedDate":"1987-06-23","source":{"name":"中国法律法规汇编（项目数据资源）","url":""},"summary":{"zh":""},"catalogCategory":"法律"},"summary":{"zh":""}};
